composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      MONGO_URL: "mongodb://{{serviceName}}-mongo:27017/wekan"
      ROOT_URL: {{env.ROOT_URL}}
  {{serviceName}}-mongo:
    image: mongo:6
    container_name: {{serviceName}}-mongo
    restart: unless-stopped
